function UserPage() {
  const { data, isFetching } = useSuspenseQuery({
    queryKey: ['user', 1],
    queryFn: fetchUser,
  })

  return (
    <>
      {isFetching && <small>Refreshing...</small>}
      <div>{data.name}</div>
    </>
  )
}

function Repos() {
  const { data, isPending, isError } = useQuery({
    queryKey: ['repos'],
    queryFn: fetchRepos,
  })

  if (isPending) return <div>Loading...</div>
  if (isError) return <div>Error</div>

  return (
    <ul>
      {data.map((repo) => (
        <li key={repo.id}>{repo.name}</li>
      ))}
    </ul>
  )
}

import { Suspense } from 'react'
import { useSuspenseQuery } from '@tanstack/react-query'

function Repos() {
  const { data } = useSuspenseQuery({
    queryKey: ['repos'],
    queryFn: fetchRepos,
  })
  // render follows in continuation
}

return (
  <ul>
    {data.map((repo) => (
      <li key={repo.id}>{repo.name}</li>
    ))}
  </ul>
)

export default function Page() {
  return (
    <Suspense fallback={<div>Loading repos...</div>}>
      <Repos />
    </Suspense>
  )
}

function UserProfile() {
  const { data } = useSuspenseQuery({
    queryKey: ['user'],
    queryFn: fetchUser,
  })

  return <h1>{data.name}</h1>
}

import { ErrorBoundary } from 'react-error-boundary'
import { Suspense } from 'react'

function Repos() {
  const { data } = useSuspenseQuery({
    queryKey: ['repos'],
    queryFn: fetchRepos,
  })

  return (
    <ul>
      {data.map((repo) => (
        <li key={repo.id}>{repo.name}</li>
      ))}
    </ul>
  )
}

export default function Page() {
  return (
    <ErrorBoundary fallback={<div>Could not load repos</div>}>
      <Suspense fallback={<div>Loading repos...</div>}>
        <Repos />
      </Suspense>
    </ErrorBoundary>
  )
}

useQuery({
  queryKey: ['user', id],
  queryFn: () => fetchUser(id),
  enabled: !!id,
})

function User({ id }: { id?: string }) {
  const { data } = useSuspenseQuery({
    queryKey: ['user', id],
    queryFn: () => fetchUser(id!),
    // enabled: !!id  ❌ not supported
  })

  return <div>{data.name}</div>
}

function User({ id }: { id?: string }) {
  if (!id) return <div>Select a user</div>

  return (
    <Suspense fallback={<div>Loading user...</div>}>
      <UserContent id={id} />
    </Suspense>
  )
}

function UserContent({ id }: { id: string }) {
  const { data } = useSuspenseQuery({
    queryKey: ['user', id],
    queryFn: () => fetchUser(id),
  })

  return <div>{data.name}</div>
}

function Dashboard() {
  const { data: user } = useSuspenseQuery({
    queryKey: ['user'],
    queryFn: fetchUser,
  })

  const { data: repos } = useSuspenseQuery({
    queryKey: ['repos'],
    queryFn: fetchRepos,
  })

  return (
    <>
      <h1>{user.name}</h1>
      <div>{repos.length} repos</div>
    </>
  )
}
